# generated by tools/lite_build.py for mission 26 — authors: edit solutions/_navera_lite, not this copy
"""navera_lite/stars.py — a position from the stars: the clock of the sky (Julian date, sidereal time), altitude
and azimuth, latitude from Polaris, star detection in a photo, the camera's pointing from the IMU, the two
latitude roots and the prior that chooses between them, and the error budget. Part of NAVERA Lite, the
course's teaching stack (mission 26). Written for the course; it is not NAVERA code.

Conventions (courses/_lib/CONVENTIONS.md):
- Angles in DEGREES at every interface (radians only inside trigonometric calls).
- Right ascension (ra) and declination (dec) on the celestial sphere; the catalogue gives them for the
  epoch J2000, precess() moves them to the date of the photo ("of date").
- Altitude above the horizon (alt, 90° = zenith); azimuth (az) clockwise from TRUE north, in [0, 360).
- Latitude north positive, longitude EAST positive, in [−180, 180).
- Times are UTC; a Julian date (jd) counts days. gst_deg = the Greenwich sidereal time (GMST here).
- World frame ENU, body frame FLU, quaternions (x, y, z, w) body → world (missions 16–17).
- Pixels (u, v) = (column, row), origin at the top-left corner; camera frame as OpenCV (mission 18).
"""
import csv
import math
import os

import cv2
import numpy as np

from navera_lite.rotations import q_rotate

CATALOGUE_PATH = os.environ.get("NAVERA_LITE_STARS", "/data/academy/26-stars/bright_stars.csv")
KM_PER_DEG = 2.0 * math.pi * 6371.0 / 360.0   # 111.195 km: one degree of great circle on the Earth (R = 6371 km)
POLARIS_P_DEG = 0.6253                         # Polaris' polar distance 90° − dec, of date (October 2026)
CAM_TILT_DEG = 20.0                            # NAVERA Lite's star camera: its axis leans 20° from body up, towards the nose
CAM_AXIS_BODY = (math.sin(math.radians(CAM_TILT_DEG)), 0.0, math.cos(math.radians(CAM_TILT_DEG)))
R_BODY_STAR_CAM = np.array([[0.0, math.cos(math.radians(CAM_TILT_DEG)), math.sin(math.radians(CAM_TILT_DEG))],
                            [-1.0, 0.0, 0.0],                 # columns = camera axes in the body (FLU) frame:
                            [0.0, -math.sin(math.radians(CAM_TILT_DEG)), math.cos(math.radians(CAM_TILT_DEG))]])
#   image right = body right (−y); image down = towards the nose and down; optical axis = CAM_AXIS_BODY.


# ====================================================================== given: catalogue and sky helpers

# given — read it and use it, no need to change it
def load_catalogue(path=None, mag_max=6.5):
    """The star catalogue shipped with the mission: a subset of the HYG star database v4.1 (Hipparcos, Yale,
    Gliese; by D. Nash / astronexus, CC BY-SA 4.0), J2000. Returns a dict of numpy arrays, one entry per star
    brighter than mag_max (smaller magnitude = brighter): "id" (HYG number), "name" (common or Bayer name, text),
    "ra_deg", "dec_deg" (J2000), "vmag" (visual magnitude).

    Example: cat = load_catalogue(); len(cat["ra_deg"]) → 8920 stars; find_star(cat, "Polaris") → its index
    """
    path = path or CATALOGUE_PATH
    if not os.path.exists(path):
        raise FileNotFoundError(f"the star catalogue {path} is missing (the course data is not mounted here)")
    ids, name, ra, dec, mag = [], [], [], [], []
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            m = float(row["vmag"])
            if m > mag_max:
                continue
            ids.append(int(row["id"]))
            name.append(row["common"] or row["bayer"])
            ra.append(float(row["ra_deg"]))
            dec.append(float(row["dec_deg"]))
            mag.append(m)
    return {"id": np.array(ids), "name": np.array(name), "ra_deg": np.array(ra), "dec_deg": np.array(dec),
            "vmag": np.array(mag)}


# given — read it and use it, no need to change it
def find_star(cat, name):
    """Index of a star in a catalogue from load_catalogue, by its name ("Vega", "Alp Lyr", "HIP 91262").
    Raises KeyError when there is no such star.

    Example: cat["name"][find_star(cat, "Vega")] → 'Vega'
    """
    key = name.strip().lower()
    hits = np.flatnonzero(np.char.lower(cat["name"].astype(str)) == key)
    if len(hits) == 0:
        raise KeyError(f"no star called {name!r} in the catalogue")
    return int(hits[0])


# given — read it and use it, no need to change it
def precess(ra_deg, dec_deg, jd):
    """Move J2000 catalogue positions to the date jd (the Earth's axis turns slowly: precession, about
    50″ per year along the ecliptic). Rigorous rotation with the IAU 1976 angles ζ, z, θ (course-written,
    from the textbook formulas). Nutation (≤ 17″) and aberration (≤ 20″) are not included.
    Works on numbers and on numpy arrays; returns (ra_deg in [0, 360), dec_deg).

    Example: precess(279.2347, 38.7837, 2461334.5) → about (279.4598, 38.8079)   (Vega, 20 October 2026)
    """
    t = (np.asarray(jd, dtype=float) - 2451545.0) / 36525.0
    zeta = np.radians((2306.2181 * t + 0.30188 * t ** 2 + 0.017998 * t ** 3) / 3600.0)
    z = np.radians((2306.2181 * t + 1.09468 * t ** 2 + 0.018203 * t ** 3) / 3600.0)
    theta = np.radians((2004.3109 * t - 0.42665 * t ** 2 - 0.041833 * t ** 3) / 3600.0)
    a, d = np.radians(np.asarray(ra_deg, dtype=float)), np.radians(np.asarray(dec_deg, dtype=float))
    A = np.cos(d) * np.sin(a + zeta)
    B = np.cos(theta) * np.cos(d) * np.cos(a + zeta) - np.sin(theta) * np.sin(d)
    C = np.sin(theta) * np.cos(d) * np.cos(a + zeta) + np.cos(theta) * np.sin(d)
    ra = np.degrees(np.arctan2(A, B) + z) % 360.0
    dec = np.degrees(np.arcsin(np.clip(C, -1.0, 1.0)))
    if np.ndim(ra) == 0:
        return float(ra), float(dec)
    return ra, dec


# given — read it and use it, no need to change it
def radec_to_vec(ra_deg, dec_deg):
    """Unit vector(s) (x, y, z) of sky direction(s): x towards ra 0°, z towards the north celestial pole.
    Arrays in → an N × 3 array out.

    Example: radec_to_vec(90.0, 0.0) → about array([0., 1., 0.])
    """
    a, d = np.radians(np.asarray(ra_deg, dtype=float)), np.radians(np.asarray(dec_deg, dtype=float))
    return np.stack([np.cos(d) * np.cos(a), np.cos(d) * np.sin(a), np.sin(d)], axis=-1)


# given — read it and use it, no need to change it
def vec_to_radec(v):
    """(ra_deg in [0, 360), dec_deg) of a sky direction vector (any length).

    Example: vec_to_radec([0.0, 0.0, 2.0]) → (0.0, 90.0)
    """
    v = np.asarray(v, dtype=float)
    v = v / np.linalg.norm(v)
    return float(math.degrees(math.atan2(v[1], v[0])) % 360.0), float(math.degrees(math.asin(max(-1.0, min(1.0, v[2])))))


# given — read it and use it, no need to change it
def sep_deg(lat1, lon1, lat2, lon2):
    """Angle (degrees) between two directions given as (lat, lon) — or (dec, ra): the same formula. On the
    Earth, multiply by KM_PER_DEG for kilometres.

    Example: sep_deg(0.0, 0.0, 0.0, 90.0) → 90.0
    """
    v1 = radec_to_vec(lon1, lat1)
    v2 = radec_to_vec(lon2, lat2)
    return float(np.degrees(np.arctan2(np.linalg.norm(np.cross(v1, v2)), float(np.dot(v1, v2)))))


# given — read it and use it, no need to change it
def pixel_rays(pts_px, K):
    """Unit direction vectors, in the camera frame (OpenCV: x right, y down, z out of the lens), of pixels
    (u, v) seen by an ideal pinhole camera K (3 × 3). pts_px: N × 2. Returns N × 3.

    Example: pixel_rays([[640.0, 480.0]], K_from_hfov(60.0, 1280, 960)) → array([[0., 0., 1.]])
    """
    p = np.asarray(pts_px, dtype=float).reshape(-1, 2)
    K = np.asarray(K, dtype=float)
    x = (p[:, 0] - K[0, 2]) / K[0, 0]
    y = (p[:, 1] - K[1, 2]) / K[1, 1]
    r = np.stack([x, y, np.ones_like(x)], axis=1)
    return r / np.linalg.norm(r, axis=1, keepdims=True)


# given — read it and use it, no need to change it
def fit_rotation(a, b):
    """The rotation R (3 × 3) that best turns the unit vectors a (N × 3) onto b (N × 3): it minimises
    Σ |R·aᵢ − bᵢ|² (the SVD solution of Wahba's problem, the 3-D cousin of mission 22's similarity fit).

    Example: fit_rotation(np.eye(3), np.eye(3)) → the identity
    """
    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)
    U, _, Vt = np.linalg.svd(a.T @ b)
    d = np.sign(np.linalg.det(Vt.T @ U.T)) or 1.0
    return Vt.T @ np.diag([1.0, 1.0, d]) @ U.T


# given — read it and use it, no need to change it
def plate_solve(pts_px, K, ra_deg, dec_deg, vmag, n_use=12, mag_vote=4.5, tol_deg=0.02, match_px=2.0):
    """Which stars are these? A small "lost in space" plate solver, course-written (astrometry.net, which NAVERA
    uses, is a far stronger relative). pts_px: detected star centres (N × 2, BRIGHTEST FIRST, as detect_stars
    returns them); K: the camera matrix; ra_deg, dec_deg, vmag: the catalogue, already precessed to the date.

    How: (1) the angle between every two of the n_use brightest detections is compared with a table of the
    angles between catalogue stars brighter than mag_vote (angles do not depend on where the camera points);
    each agreement within tol_deg is a vote for "detection i is star s"; (2) the best-voted identities give a
    first rotation camera → sky (fit_rotation), wrong ones are dropped; (3) every catalogue star is projected
    into the image with that rotation and matched to a detection within match_px; the rotation is fitted
    again on all matches.

    Returns None when it cannot solve, else a dict: "ra_deg", "dec_deg" (the direction of the image CENTRE,
    of date), "R_eq_cam" (3 × 3: camera frame → sky vectors), "n_matched", "rms_arcsec" (fit residual), and
    "matches" (list of (detection index, catalogue index)).

    Example: plate_solve(pts, K, ra_date, dec_date, cat["vmag"]) → {"ra_deg": 301.2, "dec_deg": 58.6, ...}
    """
    pts = np.asarray(pts_px, dtype=float).reshape(-1, 2)
    if len(pts) < 5:
        return None
    K = np.asarray(K, dtype=float)
    w, h = 2.0 * K[0, 2], 2.0 * K[1, 2]
    fov = math.degrees(2.0 * math.atan(math.hypot(w / 2.0 / K[0, 0], h / 2.0 / K[1, 1]))) + 1.0
    rays = pixel_rays(pts, K)
    V = radec_to_vec(ra_deg, dec_deg)
    vmag = np.asarray(vmag, dtype=float)
    bright = np.flatnonzero(vmag <= mag_vote)
    Vb = V[bright]
    dots = Vb @ Vb.T
    ii, jj = np.nonzero(np.triu(dots > math.cos(math.radians(fov)), 1))
    ang = np.degrees(np.arccos(np.clip(dots[ii, jj], -1.0, 1.0)))
    order = np.argsort(ang)
    ang, ii, jj = ang[order], ii[order], jj[order]
    n = min(n_use, len(pts))
    votes = np.zeros((n, len(bright)), dtype=int)
    for i in range(n):
        for j in range(i + 1, n):
            a = math.degrees(math.acos(max(-1.0, min(1.0, float(rays[i] @ rays[j])))))
            lo, hi = np.searchsorted(ang, a - tol_deg), np.searchsorted(ang, a + tol_deg)
            if hi <= lo:
                continue
            both = np.concatenate([ii[lo:hi], jj[lo:hi]])
            np.add.at(votes[i], both, 1)
            np.add.at(votes[j], both, 1)
    best = votes.argmax(axis=1)
    score = votes.max(axis=1)
    keep = [i for i in np.argsort(-score) if score[i] >= 3]
    if len(keep) < 3:
        return None
    det = np.array(keep)
    cat_i = bright[best[det]]
    for _ in range(4):                                 # drop identities that disagree with the others
        if len(det) < 3:
            return None
        R = fit_rotation(rays[det], V[cat_i])
        res = np.degrees(np.arccos(np.clip(np.sum((rays[det] @ R.T) * V[cat_i], axis=1), -1.0, 1.0)))
        if res.max() < 0.1:
            break
        worst = int(np.argmax(res))
        det, cat_i = np.delete(det, worst), np.delete(cat_i, worst)
    else:
        return None
    for _ in range(2):                                 # verify with every catalogue star in the image
        cam = V @ R                                    # sky → camera: R.T @ v for every row v
        front = np.flatnonzero(cam[:, 2] > 0.05)
        uv = (cam[front] @ K.T)
        uv = uv[:, :2] / uv[:, 2:3]
        inside = (uv[:, 0] > -match_px) & (uv[:, 0] < w + match_px) & (uv[:, 1] > -match_px) & (uv[:, 1] < h + match_px)
        front, uv = front[inside], uv[inside]
        pairs, used = [], set()
        for k, p in enumerate(pts):
            if len(uv) == 0:
                break
            d2 = np.sum((uv - p) ** 2, axis=1)
            m = int(np.argmin(d2))
            if d2[m] <= match_px ** 2 and int(front[m]) not in used:
                used.add(int(front[m]))
                pairs.append((k, int(front[m])))
        if len(pairs) < 8:
            return None
        di = np.array([p[0] for p in pairs])
        ci = np.array([p[1] for p in pairs])
        R = fit_rotation(rays[di], V[ci])
    res = np.degrees(np.arccos(np.clip(np.sum((rays[di] @ R.T) * V[ci], axis=1), -1.0, 1.0)))
    ra_c, dec_c = vec_to_radec(R @ np.array([0.0, 0.0, 1.0]))
    return {"ra_deg": ra_c, "dec_deg": dec_c, "R_eq_cam": R, "n_matched": len(pairs),
            "rms_arcsec": float(math.sqrt(float(np.mean(res ** 2))) * 3600.0), "matches": pairs}


# ====================================================================== session 1 — the clock of the sky

# TODO 1 ---------------------------------------------------------------------------------------
def julian_date(y, mo, d, h=0, mi=0, s=0.0):
    """The Julian date of a UTC calendar date and time (Gregorian calendar, years after 1582): the number of
    days since noon, 1 January 4713 BC, as one float. Midnight gives a date ending in .5 (a Julian day
    starts at noon).

    Example: julian_date(2000, 1, 1, 12) → 2451545.0            (the epoch J2000.0)
             julian_date(2026, 10, 20, 20, 30) → 2461334.3541667
    """
    if mo <= 2:
        y, mo = y - 1, mo + 12
    a = math.floor(y / 100)
    b = 2 - a + math.floor(a / 4)
    day = d + (h + mi / 60.0 + s / 3600.0) / 24.0
    return math.floor(365.25 * (y + 4716)) + math.floor(30.6001 * (mo + 1)) + day + b - 1524.5


# TODO 2 ---------------------------------------------------------------------------------------
def gmst_deg(jd):
    """Greenwich Mean Sidereal Time, in DEGREES in [0, 360), at the Julian date jd (UT): the angle between the
    vernal equinox and the Greenwich meridian (IAU 1982 formula). Works on a number or a numpy array.

    Example: gmst_deg(2451545.0) → 280.46061837
             gmst_deg(2461334.3541667) → about 336.8118
    """
    d = np.asarray(jd, dtype=float) - 2451545.0
    T = d / 36525.0
    g = (280.46061837 + 360.98564736629 * d + 0.000387933 * T ** 2 - T ** 3 / 38710000.0) % 360.0
    return float(g) if np.ndim(g) == 0 else g


# TODO 3 ---------------------------------------------------------------------------------------
def altaz(ra_deg, dec_deg, lat, lon, gst_deg):
    """Where a star appears in the observer's sky: altitude (degrees above the horizon, negative = below it)
    and azimuth (degrees clockwise from TRUE north, in [0, 360)), for a star at (ra_deg, dec_deg) of date,
    an observer at (lat, lon) (longitude EAST positive) and the Greenwich sidereal time gst_deg.
    ra_deg and dec_deg may be numpy arrays (one value per star): then alt and az are arrays too.

    Example: altaz(279.4596, 38.8078, 35.83, 10.64, 336.8118) → about (37.13, 295.02)
             (Vega from Sousse, 20 October 2026, 20:30 UTC: 37° up, in the west-north-west)
    """
    ra, dec = np.radians(np.asarray(ra_deg, dtype=float)), np.radians(np.asarray(dec_deg, dtype=float))
    phi = math.radians(lat)
    H = np.radians(float(gst_deg) + float(lon)) - ra
    sin_a = np.sin(dec) * math.sin(phi) + np.cos(dec) * math.cos(phi) * np.cos(H)
    alt = np.degrees(np.arcsin(np.clip(sin_a, -1.0, 1.0)))
    az = np.degrees(np.arctan2(-np.cos(dec) * np.sin(H),
                               np.sin(dec) * math.cos(phi) - np.cos(dec) * math.sin(phi) * np.cos(H))) % 360.0
    if np.ndim(alt) == 0:
        return float(alt), float(az)
    return alt, az


# TODO 4 ---------------------------------------------------------------------------------------
def lat_from_polaris(alt_deg, ha_deg=None, p_deg=POLARIS_P_DEG):
    """Latitude (degrees) from the measured altitude of Polaris. Without its hour angle (ha_deg=None) the best
    guess is the altitude itself; with it, correct for Polaris' small circle around the pole, of radius p_deg
    (its polar distance), to first order in p.

    Example: lat_from_polaris(50.0) → 50.0
             lat_from_polaris(50.0, 60.0) → about 49.687          (0.6253° × cos 60° = 0.313° below)
    """
    if ha_deg is None:
        return float(alt_deg)
    return float(alt_deg) - float(p_deg) * math.cos(math.radians(float(ha_deg)))


# ====================================================================== session 2 — a fix from a photo

# TODO 5 ---------------------------------------------------------------------------------------
def detect_stars(gray, k_sigma=5.0, min_area=3, max_area=150):
    """Find the stars in a night photo. gray: a 2-D uint8 image. A star is a small group of touching pixels
    (8-connected) brighter than the local sky background by more than k_sigma × the noise σ of the image,
    with min_area to max_area pixels (a single hot pixel or a long aircraft trail is not a star). Its centre
    is the brightness-weighted mean position of its pixels, the background removed; its flux is the sum of
    those pixels above the background.

    Returns (pts, flux): pts an N × 2 float array of (u, v) = (column, row) centres in pixels, flux an array of
    N floats, both sorted BRIGHTEST FIRST. No star → arrays of shapes (0, 2) and (0,).
    Example: a 9 × 9 black image with one 3 × 3 block [[10, 20, 10], [20, 80, 40], [10, 20, 10]] centred on
             row 4, column 4 → pts about [[4.0909, 4.0]], flux [220.0]
    """
    g = np.asarray(gray)
    if g.ndim != 2:
        raise ValueError(f"gray must be a 2-D (grey) image, got shape {g.shape}")
    g8 = g.astype(np.uint8)
    bg = cv2.medianBlur(g8, 21).astype(np.float64)
    resid = g8.astype(np.float64) - bg
    sigma = 1.4826 * float(np.median(np.abs(resid - np.median(resid))))
    sigma = max(sigma, 0.5)
    mask = (resid > k_sigma * sigma).astype(np.uint8)
    n, labels, stats, _ = cv2.connectedComponentsWithStats(mask, connectivity=8)
    if n <= 1:
        return np.zeros((0, 2)), np.zeros(0)
    w = np.where(labels > 0, resid, 0.0)
    rows, cols = np.indices(g8.shape)
    lab = labels.ravel()
    flux = np.bincount(lab, w.ravel(), minlength=n)
    su = np.bincount(lab, (w * cols).ravel(), minlength=n)
    sv = np.bincount(lab, (w * rows).ravel(), minlength=n)
    area = stats[:, cv2.CC_STAT_AREA]
    ok = np.flatnonzero((area >= min_area) & (area <= max_area) & (flux > 0))
    ok = ok[ok > 0]
    pts = np.stack([su[ok] / flux[ok], sv[ok] / flux[ok]], axis=1)
    order = np.argsort(-flux[ok], kind="stable")
    return pts[order], flux[ok][order]


# TODO 6 ---------------------------------------------------------------------------------------
def boresight_altaz(q_body, cam_axis_body=CAM_AXIS_BODY):
    """Where the star camera points, from the vehicle's attitude: q_body (x, y, z, w), body → world ENU with
    TRUE north (an IMU's magnetic-north attitude must be turned to true north first); cam_axis_body: the
    camera's optical axis in the body frame (FLU). Returns (alt_deg, az_deg): altitude above the horizon and
    azimuth clockwise from true north in [0, 360).

    Example: boresight_altaz((0.0, 0.0, 0.7071068, 0.7071068)) → about (70.0, 0.0)
             (level, nose north: the camera leans 20° towards the nose, so it looks north, 70° high)
    """
    v = np.asarray(q_rotate(q_body, cam_axis_body), dtype=float)
    v = v / np.linalg.norm(v)
    alt = math.degrees(math.asin(max(-1.0, min(1.0, float(v[2])))))
    az = math.degrees(math.atan2(float(v[0]), float(v[1]))) % 360.0
    return alt, az


# TODO 7 ---------------------------------------------------------------------------------------
def both_roots(alt_deg, az_deg, ra_deg, dec_deg, gst_deg):
    """The observer's possible positions when a direction is known twice: in the local sky (alt_deg, az_deg,
    from the IMU) and on the celestial sphere (ra_deg, dec_deg of date, from the plate solve), at the
    Greenwich sidereal time gst_deg. The altitude equation has two latitude solutions in general.
    Returns a list of the VALID roots (latitude within [−90, 90]): 0, 1 or 2 tuples (lat, lon), longitude in
    [−180, 180), the root from asin first.

    Example: both_roots(37.13, 295.02, 279.4596, 38.8078, 336.8118)
             → about [(35.83, 10.64), (85.80, 54.66)]     (Vega seen 37° up in the WNW: Sousse, or near the pole)
    """
    a, A = math.radians(alt_deg), math.radians(az_deg)
    dec = math.radians(dec_deg)
    p = math.sin(a)
    q = math.cos(a) * math.cos(A)
    R = math.hypot(p, q)
    if R == 0.0 or abs(math.sin(dec)) > R:
        return []
    psi = math.atan2(q, p)
    x = math.asin(math.sin(dec) / R)
    out = []
    for phi_psi in (x, math.pi - x):
        phi = (phi_psi - psi + math.pi) % (2.0 * math.pi) - math.pi
        if abs(phi) > math.pi / 2.0 + 1e-12:
            continue
        H = math.atan2(-math.cos(a) * math.sin(A), math.sin(a) * math.cos(phi) - math.cos(a) * math.sin(phi) * math.cos(A))
        lon = (ra_deg + math.degrees(H) - gst_deg + 180.0) % 360.0 - 180.0
        root = (math.degrees(phi), lon)
        if not any(abs(root[0] - r[0]) < 1e-9 and abs(root[1] - r[1]) < 1e-9 for r in out):
            out.append(root)
    return out


# TODO 8 ---------------------------------------------------------------------------------------
def choose(roots, prior_lat, prior_lon, max_sep_deg=5.0):
    """Pick the root that matches a prior position (the operating area, the last trusted fix): keep the roots
    within max_sep_deg (great-circle angle) of the prior. Exactly one → return it (a (lat, lon) tuple). None or
    both → return None: no position is better than a guess.

    Example: choose([(35.8, 10.6), (37.5, 6.7)], 36.0, 10.0, max_sep_deg=1.0) → (35.8, 10.6)
             choose([(35.8, 10.6), (37.5, 6.7)], 36.0, 10.0) → None      (both within 5°: cannot tell)
    """
    near = [tuple(r) for r in roots if sep_deg(r[0], r[1], prior_lat, prior_lon) <= max_sep_deg]
    return near[0] if len(near) == 1 else None


# TODO 9 ---------------------------------------------------------------------------------------
def error_km(tilt_deg, heading_deg=0.0, alt_deg=90.0):
    """Expected position error (km, one σ) of a star fix caused by attitude errors: a tilt error of tilt_deg
    (roll and pitch together) and a heading error of heading_deg, for a camera pointing alt_deg above the
    horizon. The two errors are independent. Uses KM_PER_DEG.

    Example: error_km(0.2, 1.0, 60.0) → about 59.88
    """
    return KM_PER_DEG * math.hypot(float(tilt_deg), float(heading_deg) * math.cos(math.radians(float(alt_deg))))
